#!/usr/bin/env python3
"""Temporarily install P4 outputs on Linux and verify Fontconfig/FreeType/HarfBuzz.

Requires freetype-py, uharfbuzz and fontTools. Run after p4_variable_acceptance.py.
Only the temporary directory created by this script is removed.
"""

import argparse
import json, shutil, subprocess, tempfile
from pathlib import Path
import freetype
import uharfbuzz as hb
from fontTools.ttLib import TTFont

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument(
    "output", type=Path, help="Directory generated by p4_variable_acceptance.py"
)
root = parser.parse_args().output
font_home = Path.home() / ".local/share/fonts"
font_home.mkdir(parents=True, exist_ok=True)
evidence = []
with tempfile.TemporaryDirectory(prefix="fontcarver-p4-", dir=font_home) as temporary:
    installed = Path(temporary)
    for source in sorted(root.glob("*-Variable.*")):
        path = installed / source.name
        shutil.copy2(source, path)
        face = freetype.Face(str(path))
        info = face.get_variation_info()
        assert len(info.axes) == 1 and info.axes[0].tag == "wght"
        font = TTFont(source)
        codepoints = [cp for cp in font.getBestCmap() if cp != 32][:16]
        rendered = 0
        for weight in [400, 475, 550, 625, 700]:
            face.set_var_design_coords([weight])
            for cp in codepoints:
                for size in [16, 32]:
                    face.set_pixel_sizes(0, size)
                    face.load_char(
                        chr(cp), freetype.FT_LOAD_RENDER | freetype.FT_LOAD_NO_HINTING
                    )
                    assert face.glyph.bitmap.width > 0 and face.glyph.bitmap.rows > 0
                    rendered += 1
                face.load_char(
                    chr(cp),
                    freetype.FT_LOAD_NO_SCALE
                    | freetype.FT_LOAD_NO_HINTING
                    | freetype.FT_LOAD_NO_BITMAP
                    | freetype.FT_LOAD_VERTICAL_LAYOUT,
                )
                assert abs(face.glyph.advance.y - (1000 + (weight - 400) / 3)) <= 1, (
                    source.name,
                    cp,
                    weight,
                    face.glyph.advance.y,
                )
            hfont = hb.Font(hb.Face(source.read_bytes()))
            hfont.scale = (font["head"].unitsPerEm, font["head"].unitsPerEm)
            hfont.set_variations({"wght": weight})
            buffer = hb.Buffer()
            buffer.add_str("".join(map(chr, codepoints)))
            buffer.guess_segment_properties()
            buffer.direction = "ttb"
            hb.shape(hfont, buffer, {"vert": True, "vkrn": True})
            assert all(info.codepoint != 0 for info in buffer.glyph_infos)
            assert all(
                abs(position.y_advance + (1000 + (weight - 400) / 3)) <= 1
                for position in buffer.glyph_positions
            )
        evidence.append(
            {
                "file": path.name,
                "rendered_glyph_samples": rendered,
                "freetype_variable_vertical_metrics": True,
                "harfbuzz_vertical_metrics": True,
            }
        )
    subprocess.run(["fc-cache", "-f", str(installed)], check=True)
    listed = subprocess.check_output(["fc-list", "--format", "%{file}\n"], text=True)
    assert all(str(installed / item["file"]) in listed for item in evidence)
    matches = {}
    for family in ["FontCarverP4Latin", "FontCarverP4CJK"]:
        match = subprocess.check_output(
            ["fc-match", "--format", "%{family}\n%{file}\n", family], text=True
        )
        assert str(installed) in match
        matches[family] = match
    (root / "installation.json").write_text(
        json.dumps(
            {
                "checks": evidence,
                "fontconfig_matches": matches,
                "cleanup": "The temporary installed fonts were removed after verification.",
            },
            indent=2,
        )
        + "\n"
    )
subprocess.run(["fc-cache", "-f", str(font_home)], check=True)
print(json.dumps(evidence, indent=2))
